using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using SoopaDriveTool.Core;
namespace SoopaDriveTool.Windows;
public partial class MainWindow
{
    void ProtectedImages()
    {
        var disk=DiskPicker(false,"protected-image");var repository=new TextBox{IsReadOnly=true};var password=new PasswordBox();var scratch=new TextBox{IsReadOnly=true};var policy=Choices("Incremental","Full","Differential");var kind=Choices("Offline raw disk · all sectors, compressed and deduplicated","Live Windows · VSS writers and Windows metadata");var snapshots=new ComboBox{DisplayMemberPath="Id"};
        var controls=Stack(T("Disk and Windows images",20,Ink,true),T("Disk images use the backup repository format and support AES-256-GCM encryption. Full, incremental and differential points are independently restorable. Keep your passphrase and recovery media separately.",12,Muted),disk,kind,T("Image repository",12,Muted),repository,Btn("Choose image repository…",()=>repository.Text=PickFolder("Choose image repository on another physical disk")??repository.Text),T("Passphrase (empty creates an unencrypted repository)",12,Muted),password,policy,T("Scratch folder for Windows images / restore",12,Muted),scratch,Btn("Choose scratch…",()=>scratch.Text=PickFolder("Choose scratch storage on another physical disk")??scratch.Text));
        controls.Children.Add(Btn("Create and verify image",async()=>{if(disk.SelectedItem is not DiskInfo d)throw new IOException("Select a source.");string? secret=password.Password.Length==0?null:password.Password;await RunTaskWithActivity("Creating protected image",async(p,ct)=>{string id=kind.SelectedIndex==0?await ProtectedImageService.CaptureRawAsync(d,repository.Text,secret,(string)policy.SelectedItem,p,ct):await ProtectedImageService.CaptureWindowsAsync(d,d.Partitions.Single(x=>x.IsBoot),repository.Text,secret,(string)policy.SelectedItem,scratch.Text,p,ct);MessageBox.Show(this,"Image created and verified:\n"+id);});},true));
        controls.Children.Add(Btn("Load image restore points",async()=>{using var vault=await VaultBackup.OpenAsync(repository.Text,password.Password.Length==0?null:password.Password);snapshots.ItemsSource=await vault.ListAsync();if(snapshots.Items.Count>0)snapshots.SelectedIndex=snapshots.Items.Count-1;}));controls.Children.Add(snapshots);
        controls.Children.Add(Btn("Verify selected image",async()=>{if(snapshots.SelectedItem is not VaultSummary s)throw new IOException("Select a restore point.");await RunTaskWithActivity("Verifying protected image",async(p,ct)=>{using var vault=await VaultBackup.OpenAsync(repository.Text,password.Password.Length==0?null:password.Password,ct:ct);await vault.VerifyAsync(s.Id,ct:ct,activity:p);});}));
        controls.Children.Add(Btn("Export verified image resources…",async()=>{if(snapshots.SelectedItem is not VaultSummary s)throw new IOException("Select a restore point.");string? folder=PickFolder("Choose an empty export folder");if(folder==null)return;await RunTaskWithActivity("Exporting image resources",(p,ct)=>ProtectedImageService.ExportAsync(repository.Text,password.Password.Length==0?null:password.Password,s.Id,folder,p,ct));}));
        controls.Children.Add(Btn("Attach selected raw image read-only…",async()=>{if(snapshots.SelectedItem is not VaultSummary s)throw new IOException("Select a raw image point.");var save=new Microsoft.Win32.SaveFileDialog{Filter="Read-only browse VHD|*.vhd",FileName="SoopaDriveTool-image.vhd"};if(save.ShowDialog(this)!=true)return;await RunTaskWithActivity("Preparing read-only image browsing",(p,ct)=>ImageBrowseService.MountReadOnlyAsync(repository.Text,password.Password.Length==0?null:password.Password,s.Id,save.FileName,p,ct));}));
        controls.Children.Add(Btn("Detach browsing VHD…",async()=>{var file=PickFile("Exported browsing image|*.vhd");if(file!=null)await ImageBrowseService.DetachAsync(file);}));
        controls.Children.Add(Btn("Extract a selected path from exported WIM…",async()=>{var wim=PickFile("Exported WIM image|*.wim");if(wim==null)return;var path=Prompt("Select image path","Relative file or folder within image 1. Export the protected image resources first.","Users");if(path==null)return;var folder=PickFolder("Choose an empty extraction folder");if(folder==null)return;await RunTaskWithActivity("Extracting selected WIM content",(p,ct)=>ImageBrowseService.ExtractWimPathAsync(wim,path,folder,p,ct));}));
        controls.Children.Add(Btn("Restore selected raw image to selected disk…",async()=>{if(disk.SelectedItem is not DiskInfo d||snapshots.SelectedItem is not VaultSummary s)throw new IOException("Select an offline destination disk and restore point.");if(Prompt("Review image restore","All data on "+d.Display+" is replaced. Type exactly DISK "+d.Number)!="DISK "+d.Number)return;await RunTaskWithActivity("Restoring protected image",(p,ct)=>ProtectedImageService.RestoreRawAsync(d,repository.Text,password.Password.Length==0?null:password.Password,s.Id,p,ct),false);}));body.Children.Add(Card(controls));
    }
}
